CREATE ROLE app LOGIN NOSUPERUSER NOINHERIT;
CREATE ROLE invoice_purge_owner NOLOGIN NOSUPERUSER NOINHERIT;

CREATE TABLE accounts (id text PRIMARY KEY, is_demo boolean NOT NULL);
CREATE TABLE orders (id text PRIMARY KEY, account_id text NOT NULL REFERENCES accounts(id), state text NOT NULL DEFAULT 'NEW');
CREATE TABLE invoice_audit (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id) ON DELETE RESTRICT);

CREATE FUNCTION reject_audit_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' AND current_user = 'invoice_purge_owner' THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'immutable';
END $$;
CREATE TRIGGER invoice_audit_immutable BEFORE UPDATE OR DELETE ON invoice_audit
  FOR EACH ROW EXECUTE FUNCTION reject_audit_change();

CREATE FUNCTION complete_order(order_id text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO public.invoice_audit(order_id) VALUES (complete_order.order_id);
  UPDATE public.orders SET state = 'DONE' WHERE id = complete_order.order_id;
END $$;

CREATE FUNCTION purge_demo_account(account_id text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $$
DECLARE
  unhandled record;
BEGIN
  -- Lock the parent tables before inspecting constraints, preventing concurrent
  -- foreign key additions from invalidating the preflight during this purge.
  LOCK TABLE public.accounts, public.orders, public.invoice_audit IN SHARE ROW EXCLUSIVE MODE;
  IF NOT EXISTS (SELECT 1 FROM public.accounts a WHERE a.id = purge_demo_account.account_id AND a.is_demo) THEN
    RETURN;
  END IF;

  SELECT c.conname, c.conrelid::regclass AS source_table INTO unhandled
  FROM pg_catalog.pg_constraint c
  WHERE c.contype = 'f'
    AND c.confrelid IN ('public.accounts'::regclass, 'public.orders'::regclass, 'public.invoice_audit'::regclass)
    AND c.confdeltype IN ('a', 'r')
    AND NOT (c.conrelid = 'public.orders'::regclass AND c.confrelid = 'public.accounts'::regclass AND c.conname = 'orders_account_id_fkey')
    AND NOT (c.conrelid = 'public.invoice_audit'::regclass AND c.confrelid = 'public.orders'::regclass AND c.conname = 'invoice_audit_order_id_fkey')
  LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'unhandled foreign key % on %', unhandled.conname, unhandled.source_table USING ERRCODE = 'P0001';
  END IF;

  DELETE FROM public.invoice_audit i USING public.orders o
    WHERE i.order_id = o.id AND o.account_id = purge_demo_account.account_id;
  DELETE FROM public.orders o WHERE o.account_id = purge_demo_account.account_id;
  DELETE FROM public.accounts a WHERE a.id = purge_demo_account.account_id AND a.is_demo;
END $$;

REVOKE CREATE ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO invoice_purge_owner;
GRANT SELECT, DELETE ON accounts, orders, invoice_audit TO invoice_purge_owner;
ALTER FUNCTION purge_demo_account(text) OWNER TO invoice_purge_owner;
REVOKE ALL ON FUNCTION purge_demo_account(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION purge_demo_account(text) TO app;
GRANT SELECT, INSERT, UPDATE, DELETE ON accounts, orders TO app;
GRANT SELECT, INSERT ON invoice_audit TO app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO app;
